qc-paper);color:var(--qc-ink);font:inherit}.qc-form .qc-check{display:flex;align-items:center;gap:10px;min-height:44px}.qc-form input[type=checkbox]{width:20px;min-height:20px;height:20px;flex-shrink:0}.qc-cart-page{max-width:820px}.qc-form [role=status]{min-height:24px;font-size:13px}.qc-tag{background:var(--qc-cream);padding:6px 10px;border-radius:20px;font-size:11px}.qc-checkout-terms{font-size:12px;display:flex;gap:10px;align-items:flex-start;padding-block:14px}.qc-checkout-terms input{min-width:20px;min-height:20px}.qc-integration-note{font-size:12px;color:var(--qc-muted)}.qc-notify{margin-block:12px}.qc-notify summary{min-height:44px;cursor:pointer;font-size:12px;font-weight:700}.qc-card>.qc-notify{padding-inline:12px}.qc-form button{justify-self:start}.qc-terms-error{font-size:12px}.qc-header{isolation:isolate}.qc-home:has(dialog[open]) .qc-mobile-tabs{z-index:22}@media(max-width:749px){.qc-mega{display:none}.qc-header-row{gap:8px}.qc-header-actions{gap:0}.qc-wordmark{font-size:26px}.qc-location select{max-width:130px}.qc-header-actions>a{min-width:36px}.qc-header-actions>button{display:none}.qc-logo-image{max-width:100px}.qc-header-row>.qc-location{margin-inline-start:auto}}


