(() => {
  const header = document.querySelector('.qc-header');
  const update = () => {
    const height = header ? Math.ceil(header.getBoundingClientRect().height) : 0;
    document.querySelectorAll('[data-category-sidebar]').forEach(sidebar => {
      sidebar.style.setProperty('--qc-sidebar-top', `${height + 12}px`);
    });
  };
  update();
  const revealCurrent = () => {
    document.querySelectorAll('[data-category-sidebar]').forEach(sidebar => {
      const current = sidebar.querySelector('[aria-current="page"]');
      if (!current) return;
      const item = current.getBoundingClientRect(), bounds = sidebar.getBoundingClientRect();
      if (item.bottom > bounds.bottom - 16 || item.top < bounds.top) {
        sidebar.scrollTop += item.top - bounds.top - sidebar.clientHeight / 3;
      }
    });
  };
  requestAnimationFrame(revealCurrent);
  if (header && 'ResizeObserver' in window) new ResizeObserver(update).observe(header);
  window.addEventListener('resize', update, {passive:true});
  document.addEventListener('shopify:section:load', () => {update();requestAnimationFrame(revealCurrent);});
})();

{% doc %}
Collection navigation from the merchant's three-level catalogue menu.
@param {linklist} menu - Catalogue menu.
@param {collection} current_collection - Displayed collection.
{% enddoc %}
{% assign active_department = blank %}
{% assign active_group = blank %}
{% for department in menu.links %}
  {% if department.url == current_collection.url %}{% assign active_department = department %}{% endif %}
  {% for group in department.links %}
    {% if group.url == current_collection.url %}{% assign active_department = department %}{% assign active_group = group %}{% endif %}
    {% for leaf in group.links %}
      {% if leaf.url == current_collection.url %}{% assign active_department = department %}{% assign active_group = group %}{% endif %}
    {% endfor %}
  {% endfor %}
{% endfor %}
<aside class="qc-collection-sidebar" data-category-sidebar>
  <h2 class="qc-sidebar-heading">{{ 'qc.categories' | t }}</h2>
  <nav aria-label="{{ 'qc.browse_categories' | t }}">
    {% for department in menu.links %}
      {% if department.links != blank %}
        <details class="qc-sidebar-department"{% if active_department.url == department.url %} open{% endif %}>
          <summary{% if active_department.url == department.url %} class="qc-sidebar-branch"{% endif %}>
            {% render 'qc-category-label', category: department.object, title: department.title %}
            <span class="qc-sidebar-chevron" aria-hidden="true">⌄</span>
          </summary>
          <ul class="qc-sidebar-groups" role="list">
            <li><a class="qc-sidebar-overview" href="{{ department.url }}"{% if department.url == current_collection.url %} aria-current="page"{% endif %}>{{ 'qc.view_all' | t }} {{ department.title | escape }}</a></li>
            {% for group in department.links %}
              <li>
                <a href="{{ group.url }}"{% if group.url == current_collection.url %} aria-current="page"{% elsif active_group.url == group.url %} class="qc-sidebar-ancestor"{% endif %}>{{ group.title | escape }}</a>
                {% if active_group.url == group.url and group.links != blank %}
                  <ul class="qc-sidebar-leaves" role="list">
                    {% for leaf in group.links %}<li><a href="{{ leaf.url }}"{% if leaf.url == current_collection.url %} aria-current="page"{% endif %}>{{ leaf.title | escape }}</a></li>{% endfor %}
                  </ul>
                {% endif %}
              </li>
            {% endfor %}
          </ul>
        </details>
      {% else %}
        <a class="qc-sidebar-direct" href="{{ department.url }}"{% if department.url == current_collection.url %} aria-current="page"{% endif %}>{% render 'qc-category-label', category: department.object, title: department.title %}</a>
      {% endif %}
    {% else %}
      <a class="qc-sidebar-direct" href="{{ routes.all_products_collection_url }}"{% if current_collection.handle == 'all' %} aria-current="page"{% endif %}>{% render 'qc-icon', name: 'grid' %}{{ 'qc.view_all' | t }}</a>
    {% endfor %}
  </nav>
</aside>

{% assign show_sidebar = false %}
{% if template.name == 'collection' and section.settings.show_category_sidebar != false %}{% assign show_sidebar = true %}{% endif %}
{% if show_sidebar %}{{ 'qc-category-sidebar.css' | asset_url | stylesheet_tag }}{% endif %}
<section class="qc-wrap qc-section{% if show_sidebar %} qc-collection-layout{% endif %}">
  {% if show_sidebar %}
    {% assign sidebar_menu = section.settings.sidebar_menu | default: settings.qc_catalog_menu %}
    {% render 'qc-collection-sidebar', menu: sidebar_menu, current_collection: collection %}
  {% endif %}
  <div class="qc-catalog-content">
    <h1>{% if template.name == 'search' %}{{ 'qc.search' | t }}{% else %}{{ collection.title | escape }}{% endif %}</h1>
    {% if template.name == 'search' %}
      <form class="qc-inline-search" action="{{ routes.search_url }}" role="search"><label>{{ 'qc.search' | t }}<input name="q" type="search" value="{{ search.terms | escape }}"></label><input name="type" type="hidden" value="product"><button class="qc-button">{{ 'qc.search' | t }}</button></form>
      {% assign source = search %}
    {% else %}
      {% if collection.description != blank %}<div class="qc-prose">{{ collection.description }}</div>{% endif %}
      {% assign source = collection %}
    {% endif %}
    {% render 'qc-filters', results: source %}
    {% assign shown = 0 %}
    {% if template.name == 'search' %}
      {% paginate search.results by section.settings.limit %}
        <div class="qc-products qc-grid">
          {% for item in search.results %}{% if item.object_type == 'product' %}{% if item.available or item.metafields.custom.show_when_sold_out.value == true %}{% render 'qc-product-card', product: item %}{% assign shown = shown | plus: 1 %}{% endif %}{% endif %}{% endfor %}
          {% if shown == 0 %}<p class="qc-empty">{{ 'qc.search_empty' | t }}</p>{% endif %}
        </div>
        {% render 'pagination', paginate: paginate %}
      {% endpaginate %}
    {% else %}
      {% paginate collection.products by section.settings.limit %}
        <div class="qc-products qc-grid">
          {% for item in collection.products %}{% if item.available or item.metafields.custom.show_when_sold_out.value == true %}{% render 'qc-product-card', product: item %}{% assign shown = shown | plus: 1 %}{% endif %}{% endfor %}
          {% if shown == 0 %}<div class="qc-empty"><h2>{{ 'qc.empty_collection' | t }}</h2><p>{{ 'qc.category_empty_help' | t }}</p></div>{% endif %}
        </div>
        {% render 'pagination', paginate: paginate %}
      {% endpaginate %}
    {% endif %}
  </div>
</section>
{% if show_sidebar %}<script src="{{ 'qc-category-sidebar.js' | asset_url }}" defer></script>{% endif %}
{% schema %}
{
  "name": "catalog",
  "settings": [
    {
      "type": "range",
      "id": "limit",
      "label": "Products per page",
      "min": 12,
      "max": 48,
      "step": 12,
      "default": 24
    },
    {
      "type": "checkbox",
      "id": "show_category_sidebar",
      "label": "Show category sidebar",
      "default": true
    },
    {
      "type": "link_list",
      "id": "sidebar_menu",
      "label": "Sidebar menu",
      "info": "Uses the Storefront and delivery catalogue menu when left blank."
    }
  ],
  "presets": [
    {
      "name": "catalog"
    }
  ]
}
{% endschema %}

{% doc %}Shared cart contents for page and drawer, refreshed through Section Rendering API.{% enddoc %}
<div data-cart-render><div class="qc-cart-items">{% for item in cart.items %}<article class="qc-cart-item">{% if item.image %}{{ item.image | image_url: width: 160 | image_tag: loading: 'lazy', widths: '80, 160', sizes: '80px' }}{% else %}{% render 'qc-product-placeholder', product: item.product %}{% endif %}<div><a href="{{ item.url }}">{{ item.product.title | remove_first: '[TEST] ' | escape }}</a>{% unless item.product.has_only_default_variant %}<small>{{ item.variant.title | escape }}</small>{% endunless %}<strong>{{ item.final_line_price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong>{% for discount in item.line_level_discount_allocations %}<small>{{ discount.discount_application.title | escape }} (−{{ discount.amount | money_without_currency | prepend: ' ' | prepend: shop.currency }})</small>{% endfor %}<div class="qc-stepper"><button type="button" data-line-key="{{ item.key }}" data-quantity="{{ item.quantity | minus: 1 }}" aria-label="{{ 'qc.decrease' | t }}">−</button><span>{{ item.quantity }}</span><button type="button" data-line-key="{{ item.key }}" data-quantity="{{ item.quantity | plus: 1 }}" aria-label="{{ 'qc.increase' | t }}">+</button></div><button type="button" class="qc-remove" data-line-key="{{ item.key }}" data-quantity="0">{{ 'qc.remove' | t }}</button></div></article>{% else %}<div class="qc-empty">{% render 'qc-icon', name: 'bag' %}<h3>{{ 'qc.empty_cart' | t }}</h3><a href="{{ routes.all_products_collection_url }}" class="qc-button">{{ 'qc.continue' | t }}</a></div>{% endfor %}</div>
{% if cart.item_count > 0 %}{% assign lower = settings.qc_mid_threshold | default: 49 | times: 100 %}{% assign upper = settings.qc_free_delivery | default: 99 | times: 100 %}{% assign fee = settings.qc_fee_low | default: '5.99' | times: 100 | round %}{% if cart.total_price >= upper %}{% assign fee = 0 %}{% elsif cart.total_price >= lower %}{% assign fee = settings.qc_fee_mid | default: '3.99' | times: 100 | round %}{% endif %}
{% if upper > 0 %}{% assign progress = cart.total_price | times: 100.0 | divided_by: upper | at_most: 100 %}<div class="qc-free-delivery">{% if cart.total_price >= upper %}<p>{{ 'qc.free' | t }}</p>{% else %}{% assign remaining = upper | minus: cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency %}<p>{{ 'qc.until_free' | t: amount: remaining }}</p>{% endif %}<div class="qc-progress" role="progressbar" aria-label="{{ 'qc.free' | t }}" aria-valuenow="{{ progress | round }}" aria-valuemin="0" aria-valuemax="100"><span style="transform:scaleX({{ progress | divided_by: 100.0 }})"></span></div>{% if cart.total_price < lower %}{% assign next_remaining = lower | minus: cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency %}{% assign middle_fee = settings.qc_fee_mid | default: '3.99' | times: 100 | round | money_without_currency | prepend: ' ' | prepend: shop.currency %}<p>{{ 'qc.free_next_tier' | t: amount: next_remaining, fee: middle_fee }}</p>{% endif %}</div>{% endif %}
<div class="qc-cart-total"><span>{{ 'qc.subtotal' | t }}</span><strong>{{ cart.total_price | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong></div><div class="qc-cart-total qc-estimated-fee"><span>{{ 'qc.delivery_fee' | t }}</span><strong>{{ fee | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong></div><div class="qc-cart-total qc-cart-estimate"><span>{{ 'qc.estimated_total' | t }}</span><strong>{{ cart.total_price | plus: fee | money_without_currency | prepend: ' ' | prepend: shop.currency }}</strong></div><p class="qc-muted">{{ settings.qc_vat_note | escape }}. {{ 'qc.delivery_final' | t }}</p><div class="qc-cart-area">{% render 'qc-area-picker' %}</div>{% render 'qc-delivery-picker' %}<p class="qc-integration-note" data-zone-status></p>
<form action="{{ routes.cart_url }}" method="post" class="qc-checkout-form" data-checkout-form><label class="qc-checkout-terms"><input type="checkbox" name="attributes[terms_accepted]" value="yes" data-terms required><span>{{ 'qc.terms_prefix' | t }} <a href="{{ shop.terms_of_service.url | default: '/pages/terms-conditions' }}">{{ 'qc.terms_link' | t }}</a></span></label><p class="qc-terms-error" role="status"></p><button name="checkout" class="qc-button qc-checkout">{{ 'qc.checkout' | t }} ↗</button></form><div class="qc-policy-links">{% render 'qc-policy-links' %}</div>{% endif %}</div>
